class LikeResult {
  const LikeResult({required this.matched, this.matchId, required this.likesRemainingToday});

  final bool matched;
  final String? matchId;
  final int likesRemainingToday;

  factory LikeResult.fromJson(Map<String, dynamic> j) => LikeResult(
        matched: Json.flag(j, 'matched'),
        matchId: Json.optStr(j, 'matchId'),
        likesRemainingToday: Json.intg(j, 'likesRemainingToday'),
      );
}

/// Category of tags for grouped display.
class TagCategory {
  const TagCategory({required this.name, required this.tags});
  final String name;
  final List<TagItem> tags;
}

/// Individual tag item.
class TagItem {
  const TagItem({required this.id, required this.label, this.icon});
  final dynamic id;
  final String label;
  final IconData? icon;

  factory TagItem.fromJson(Map<String, dynamic> j) => TagItem(
        id: j['id'],
        label: j['label'] as String,
        icon: j['icon'] != null ? IconData(j['icon'] as int, fontFamily: 'MaterialIcons') : null,
      );
}

