34	class _PhotoGridScreenState extends ConsumerState<PhotoGridScreen> {
35	  final _picker = ImagePicker();
36	  final List<_PhotoSlot> _slots = [];
37	  bool _busy = false;
38	  String? _error;
39	
40	  static const int _maxPhotos = 6;
41	  static const int _minPhotos = 3;
42	  static const int _minDimension = 480; // minimum width/height in pixels
43	
44	  @override
45	  void initState() {
46	    super.initState();
47	    // Initialize slots from initial photos
48	    for (final url in widget.initialPhotos) {
49	      _slots.add(_PhotoSlot(url: url, isRemote: true));
50	    }
51	    // Fill remaining with empty slots
52	    while (_slots.length < _maxPhotos) {
53	      _slots.add(_PhotoSlot.empty());
54	    }
55	  }
56	
57	  int get _filledCount => _slots.where((s) => s.hasImage).length;
58	  bool get _canContinue => _filledCount >= _minPhotos;
59	
60	  Future<void> _addPhoto(int index) async {
61	    if (_busy) return;
62	
63	    final picked = await _picker.pickImage(
64	      source: ImageSource.gallery,
65	      maxWidth: 1600,
66	      maxHeight: 1600,
67	      imageQuality: 85,
68	    );
69	    if (picked == null) return;
70	
71	    // Client-side resolution check
72	    final bytes = await File(picked.path).readAsBytes();
73	    final codec = await instantiateImageCodec(bytes);
74	    final frame = await codec.getNextFrame();
75	    final width = frame.image.width;
76	    final height = frame.image.height;
77	
78	    if (width < _minDimension || height < _minDimension) {
79	      if (mounted) {
80	        _showError('Photo too small. Minimum ${_minDimension}×${_minDimension}px. Yours: ${width}×${height}px');
81	      }
82	      return;
83	    }
84	
85	    setState(() => _busy = true);
86	    try {
87	      final profile = ref.read(myProfileProvider).valueOrNull;
88	      final url = await Storage.upload(
89	        Storage.pathFor(profile?.userId ?? 'unknown', 'profiles'),
90	        File(picked.path),
91	      );
92	
93	      setState(() {
94	        if (index < _slots.length) {
95	          _slots[index] = _PhotoSlot(url: url, isRemote: true);
96	        } else {
97	          _slots.add(_PhotoSlot(url: url, isRemote: true));
98	        }
99	        // Ensure we have empty slots at the end
100	        while (_slots.length < _maxPhotos && _slots.last.hasImage) {
101	          _slots.add(_PhotoSlot.empty());
102	        }
103	        _error = null;
104	      });
105	      ref.invalidate(verificationProvider);
106	    } catch (e) {
107	      if (mounted) _showError('Failed to upload photo: $e');
108	    } finally {
109	      if (mounted) setState(() => _busy = false);
110	    }
111	  }
112	
113	  void _removePhoto(int index) {
114	    if (index >= _slots.length) return;
115	    setState(() {
116	      _slots.removeAt(index);
117	      // Add empty slot at the end to maintain count
118	      _slots.add(_PhotoSlot.empty());
119	    });
120	  }
121	
122	  void _setPrimary(int index) {
123	    if (index >= _slots.length || !_slots[index].hasImage) return;
124	    setState(() {
125	      final primary = _slots.removeAt(index);
126	      _slots.insert(0, primary);
127	    });
128	  }
129	
130	  void _showError(String msg) {
131	    setState(() => _error = msg);
132	    showDialog(
133	      context: context,
134	      builder: (_) => AlertDialog(
135	        backgroundColor: Tokens.tanCard,
136	        title: Text('Upload failed', style: TextStyle(color: Tokens.pinkDeep)),
137	        content: Text(msg, style: TextStyle(color: Tokens.pinkDeep)),
138	        actions: [
139	          TextButton(onPressed: () => Navigator.pop(context), child: const Text('OK', style: TextStyle(color: Tokens.pink))),
140	        ],
141	      ),
142	    );
143	  }
144	
145	  void _showHelp(BuildContext context) {
146	    showModalBottomSheet(
147	      context: context,
148	      backgroundColor: Colors.transparent,
149	      builder: (_) => Container(
150	        padding: const EdgeInsets.all(Tokens.spaceLg),
151	        decoration: const BoxDecoration(
152	          color: Tokens.tanCard,
153	          borderRadius: BorderRadius.vertical(top: Radius.circular(Tokens.radiusLg)),
154	        ),
155	        child: Column(
156	          mainAxisSize: MainAxisSize.min,
157	          children: [
158	            Container(width: 40, height: 4, decoration: BoxDecoration(color: Tokens.pink.withValues(alpha: 0.3), borderRadius: BorderRadius.circular(4))),
159	            const SizedBox(height: Tokens.spaceMd),
160	            Text('Why this question?', style: Theme.of(context).textTheme.titleMedium?.copyWith(color: Tokens.pinkDeep, fontWeight: FontWeight.w700)),
161	            const SizedBox(height: Tokens.spaceMd),
162	            Text(widget.helpText!, style: Theme.of(context).textTheme.bodyMedium?.copyWith(color: Tokens.pinkDeep), textAlign: TextAlign.center),
163	            const SizedBox(height: Tokens.spaceLg),
164	            FilledButton(onPressed: () => Navigator.pop(context), child: const Text('Got it')),
165	          ],
166	        ),
167	      ),
168	    );
169	  }
170	
171	  @override
172	  Widget build(BuildContext context) {
173	    return OnboardingScaffold(
174	      currentStep: widget.currentStep,
175	      totalSteps: widget.totalSteps,
176	      onBack: () => Navigator.of(context).pop(),
177	      onHelp: widget.helpText != null ? () => _showHelp(context) : null,
178	      showProgress: true,
179	      bottomAction: FilledButton(
180	        onPressed: _canContinue && !_busy
181	            ? () => widget.onComplete(_slots.where((s) => s.hasImage).map((s) => s.url!).toList())
182	            : null,
183	        style: FilledButton.styleFrom(
184	          minimumSize: const Size.fromHeight(52),
185	          backgroundColor: Tokens.pink,
186	          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(Tokens.radiusMd)),
187	        ),
188	        child: Text(_busy ? 'Uploading…' : 'Add photos', style: const TextStyle(fontWeight: FontWeight.w700, fontSize: 15)),
189	      ),
190	      child: Column(
191	        crossAxisAlignment: CrossAxisAlignment.start,
192	        children: [
193	          Text('Add your profile photos', style: Theme.of(context).textTheme.headlineSmall?.copyWith(color: Tokens.pinkDeep, fontWeight: FontWeight.w800)),
194	          const SizedBox(height: Tokens.spaceSm),
195	          Text('You need to upload at least $_minPhotos photos to continue. You can change them later.', style: Theme.of(context).textTheme.bodyMedium?.copyWith(color: Colors.brown.shade500)),
196	          const SizedBox(height: Tokens.spaceLg),
197	          // Photo grid
198	          GridView.count(
199	            crossAxisCount: 3,
200	            shrinkWrap: true,
201	            physics: const NeverScrollableScrollPhysics(),
202	            mainAxisSpacing: Tokens.spaceSm,
203	            crossAxisSpacing: Tokens.spaceSm,
204	            childAspectRatio: 1,
205	            children: List.generate(_maxPhotos, (i) {
206	              final slot = _slots[i];
207	              if (slot.hasImage) {
208	                return _PhotoTile(
