220	                  onTap: () => _addPhoto(i),
221	                );
222	              }
223	            }),
224	          ),
225	          const SizedBox(height: Tokens.spaceMd),
226	          // Photo guidelines link
227	          Center(
228	            child: TextButton.icon(
229	              onPressed: () {
230	                // Could navigate back to guidelines screen or show modal
231	              },
232	              icon: const Icon(Icons.info_outline, size: 16, color: Tokens.pink),
233	              label: const Text('Photo guidelines', style: TextStyle(color: Tokens.pink, fontSize: 13)),
234	            ),
235	          ),
236	          if (_error != null) ...[
237	            const SizedBox(height: Tokens.spaceMd),
238	            Text(_error!, style: TextStyle(color: Colors.red.shade700, fontSize: 13), textAlign: TextAlign.center),
239	          ],
240	        ],
